/* Conditions extracted verbatim from https://datracker.strathfield.nsw.gov.au/document/download?key=WJj6p7QcAxw=&fileName=DA2026.9 - 75 Chalmers Road STRATHFIELD - Notice of Determination (Signed).PDF (conditions-extractor-2026-08-16) — export-conditions-2026-08-16. Do not hand-edit. */
registerRefData('nsw-cond-n-1886',{"id":1886,"pan":null,"ref":"10.2026.9.1","address":"75 Chalmers Rd, Strathfield 2135 NSW","description":"Demolition of existing structures, construction of two storey dwelling with basement, inground swimming pool, cabana and secondary dwelling, front fence and associated landscape works","outcome":"approved","outcome_raw":"Approved - Delegation","outcome_source":"tracker","determined":"2026-05-29","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=WJj6p7QcAxw=&fileName=DA2026.9 - 75 Chalmers Road STRATHFIELD - Notice of Determination (Signed).PDF","sha256":"88203058a8a148f94c0c389307b49a775d5242bfe205c3db96416119ef3fd182","pages":33,"layout":"numbered","n":78,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/1886.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2026.00000009.001","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"Compliance with Building Code of Australia and insurance requirements","text":"under Home Building Act 1989\n1. It is a condition of a development consent for development that involves\nbuilding work that the work must be carried out in accordance with the\nrequirements of the Building Code of Australia.\n2. It is a condition of a development consent for development that involves\nresidential building work for which a contract of insurance is required under\nthe Home Building Act 1989, Part 6 that a contract of insurance is in force\nbefore building work authorised to be carried out by the consent\ncommences.\n3. It is a condition of a development consent for a temporary structure used as\nan entertainment venue that the temporary structure must comply with Part\nB1 and NSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for the construction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for development consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building\nCode of Australia or a fire safety standard is in force under\nthe Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021, or\nb. to the erection of a temporary building, other than a temporary\nstructure to which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"Erection of signs","text":"1. This section applies to a development consent for development involving\nbuilding work, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or\ndemolition work is being carried out-\na. showing the name, address and telephone number of the principal\ncertifier for the work, and\nb. showing the name of the principal contractor, if any, for the building\nwork and a telephone number on which the principal contractor may\nbe contacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition\nwork is being carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out inside\nan existing building, if the work does not affect the external walls of\nthe building, or\nb. Crown building work certified to comply with the Building Code of\nAustralia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"Fulfilment of BASIX commitments","text":"It is a condition of a development consent for the following that each\ncommitment listed in a relevant BASIX certificate is fulfilled-\n1. BASIX development,\nBASIX optional development, if the development application was accompanied\nby a BASIX certificate.","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"Notification of Home Building Act 1989 requirements","text":"1. This section applies to a development consent for development involving\nresidential building work if the principal certifier is not the council.\n2. It is a condition of the development consent that residential building work\nmust not be carried out unless the principal certifier for the development to\nwhich the work relates has given the council written notice of the following-\na. for work that requires a principal contractor to be appointed-\ni. the name and licence number of the principal contractor,\nand\nii. the name of the insurer of the work under the Home Building\nAct 1989, Part 6,\nb. for work to be carried out by an owner-builder-\ni. the name of the owner-builder, and\nii. if the owner-builder is required to hold an owner-builder\npermit under the Home Building Act 1989-the number of\nthe owner-builder permit.\n3. If the information notified under subsection (2) is no longer correct, it is a\ncondition of the development consent that further work must not be carried\nout unless the principal certifier has given the council written notice of the\nupdated information.\n4. This section does not apply in relation to Crown building work certified to\ncomply with the Building Code of Australia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"Shoring and adequacy of adjoining property","text":"1. This section applies to a development consent for development that involves\nexcavation that extends below the level of the base of the footings of a\nbuilding, structure or work on adjoining land, including a structure or work in\na road or rail corridor.\n2. It is a condition of the development consent that the person having the\nbenefit of the development consent must, at the person’s own expense-\na. protect and support the building, structure or work on adjoining land\nfrom possible damage from the excavation, and\nb. if necessary, underpin the building, structure or work on adjoining\nland to prevent damage from the excavation.\n3. This section does not apply if-\na. the person having the benefit of the development consent owns the\nadjoining land, or\nb. the owner of the adjoining land gives written consent to the\ncondition not applying.","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"","text":"Approved plans and supporting documentation.\nDevelopment must be carried out in accordance with the following approved\nplans and documents, except where the conditions of this consent expressly\nrequire otherwise.\nApproved Plans\nDescription Reference\nNo.\nDate Revisio\nn\nPrepared By\nDemolition plan Project\nNo.2542\nSheet No.\nA.02.1\n29.04\n.2026\nA RCO Engineering\nSediment\ncontrol plan\nProject\nNo.2542\nSheet No.\nA.03.1\n29.04\n.2026\nA RCO Engineering\n3D Views -\nSchedule of\nfinishes\nProject\nNo.2542\nSheet No.\nA.04.1\n29.04\n.2026\nA RCO Engineering\n3D Views -\nSchedule of\nFinishes\nProject\nNo.2542\nSheet No.\nA.04.2\n29.04\n.2026\nA RCO Engineering\nSite plan & site\nanalysis plan\nProject\nNo.2542\nSheet No.\nA.05.1\n29.04\n.2026\nA RCO Engineering\nSite plan & site\nanalysis plan\nProject\nNo.2542\n29.04\n.2026\nA RCO Engineering\nSheet No.\nA.05.2\nBasement floor\nplan\nProject\nNo.2542\nSheet No.\nA.06.1\n29.04\n.2026\nA RCO Engineering\nBasement -\nswept path\nProject\nNo.2542\nSheet No.\nA.06.2\n29.04\n.2026\nA RCO Engineering\nGround floor\nplan\nProject\nNo.2542\nSheet No.\nA.06.3\n29.04\n.2026\nA RCO Engineering\nFirst floor plan Project\nNo.2542\nSheet No.\nA.06.4\n29.04\n.2026\nA RCO Engineering\nRoof plan Project\nNo.2542\nSheet No.\nA.06.5\n29.04\n.2026\nA RCO Engineering\nSwimming pool\nplan and\nsections\nProject\nNo.2542\nSheet No.\nA.06.10\n29.04\n.2026\nA RCO Engineering\nEast elevation Project\nNo.2542\nSheet No.\nA.07.1\n29.04\n.2026\nA RCO Engineering\nSouth elevation Project\nNo.2542\nSheet No.\nA.07.2\n29.04\n.2026\nA RCO Engineering\nNorth elevation Project\nNo.2542\nSheet No.\nA.07.3\n29.04\n.2026\nA RCO Engineering\nWest elevation Project\nNo.2542\nSheet No.\nA.07.4\n29.04\n.2026\nA RCO Engineering\nFront fence\nelevation\nProject\nNo.2542\nSheet No.\nA.07.5\n29.04\n.2026\nA RCO Engineering\nSection 01 Project\nNo.2542\nSheet No.\nA.08.1\n29.04\n.2026\nA RCO Engineering\nSections Project\nNo.2542\nSheet No.\nA.08.2\n29.04\n.2026\nA RCO Engineering\nPool Sections Project\nNo.2542\nSheet No.\nA.08.3\n29.04\n.2026\nA RCO Engineering\nWindow\nschedule\nProject\nNo.2542\nSheet No.\nA.10.1\n29.04\n.2026\nA RCO Engineering\nLandscape\nDesign\nProject\nNo.2542\nSheet No.\nA.11.1\n29.04\n.2026\nA RCO Engineering\nLandscape\ndesign\nProject\nNo.2542\nSheet No.\nA.11.2\n29.04\n.2026\nA RCO Engineering","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"Infrastructure Development Contributions","text":"Council has identified that the development will be subject to the imposition of\nDevelopment Contributions. In accordance with Council’s relevant Contributions\nPlan, the following monetary contributions are required.\nDEVELOPMENT CONTRIBUTIONS\nStrathfield Section 94 Development $637.23\nContributions - Roads and Traffic\nManagement\nStrathfield Section 94 Development\nContributions - Local Open Space\n$2395.55\nStrathfield Section 94 Development\nContributions - Major Open Space\n$10885.99\nStrathfield Section 94 Development\nContributions - Community Facilities\n$ 2392.68\nStrathfield Section 94 Development\nContributions - Administration\n$ 206.32\nTOTAL CONTRIBUTIONS $ 16517.77\nIndexation\nThe above contributions will be indexed at the time of payment to reflect\ninflation, in accordance with the indices provided by the relevant Development\nContributions Plan. Indexation will be based on the CPI of 102.41 used to\ncalculate the above contribution amount.\nPlease email council council@strathfield.nsw.gov.au prior to the payment of\ns7.11 or s7.12 Contributions to confirm the indexed contribution payable and the\nform of payment that will be accepted by Council.\nTiming of Payment\nThe contribution must be paid and receipted by Council prior to the issue of the\nConstruction Certificate.\nA copy of the current Development Contributions Plans may be viewed on\nCouncil’s website www.strathfield.nsw.gov.au.","stage":"ongoing","stage_basis":"heading","page":8},{"label":"8","code":null,"number":"8","title":"Section 138 Roads Act 1993 & Section 68 Local Government Act 1993","text":"Unless otherwise specified by a condition of this consent, this Development\nConsent does not give any approval to undertake works on public infrastructure.\nSeparate approval is required under Section 138 of the Roads Act 1993 and Section\n68 of the Local Government Act 1993 for any of the following activities carried out\nin, on or over a public road (including the footpath) listed below.\nAn application is required to be lodged and approved prior to the commencement\nof any of the following works or activities.\n(a) If any excavation is to be supported by the use of below ground (cable) anchors\nthat are constructed under Council’s roadways/footways.\n(b) Swinging or hoisting goods over any part of a public road by means of a lift,\ncrane or the like;\n(c) Establishing a “works zone”;\n(d) Placing or storing materials or equipment;\n(e) Placing or storing waste containers or skip bins;\n(f) Stormwater & ancillary to public infrastructure on private land\n(g) Erecting a structure or carrying out work\nSeparate activity approvals for (a) -(g) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the issue of the Construction\nCertificate.\n(h) Pumping water from the site into the public road;\n(i) Constructing a vehicular crossing or footpath;\n(j) Digging up or disturbing the surface of a public road (e.g. Opening the road for\nthe purpose of connections to utility providers);\n(k) Stormwater & ancillary works in the road reserve; and\n(l) Pumping concrete from a public road;\nSeparate activity approvals for (h) -(l) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the activities commencing.\nThe relevant Application Forms for these activities can be downloaded from\nCouncil’s website\nwww.strathfield.nsw.gov.au\nFor further information, please contact Council’s Customer Service Centre on (02)\n9748 9999.","stage":"ongoing","stage_basis":"heading","page":9},{"label":"9","code":null,"number":"9","title":"Vehicular Crossing - Minor Development","text":"Constructing a vehicular crossing and footpath requires a separate approval under\nSection 138 of the Roads Act 1993 prior to the commencement of those works.\nThis approval must be obtained from Council by completing and submitting a\nworks permit application.\nThe approval for a new or modified vehicular crossing will contain the plans and\nspecifications required to construct the crossing and footpath. These works must\nbe completed prior to the issue of an Occupation Certificate.","stage":"ongoing","stage_basis":"heading","page":10},{"label":"10","code":null,"number":"10","title":"Road Opening Permit","text":"A Road Opening Permit must be obtained from Council, in the case of local or\nregional roads, or from TFNSW in the case of State roads, for every opening of a\npublic reserve to access services including sewer, stormwater drains, water mains,\ngas mains, and telecommunications before the commencement of works in the\nroad.","stage":"ongoing","stage_basis":"heading","page":10},{"label":"11","code":null,"number":"11","title":"Demolition Inspection Fees","text":"The owner/applicant is to arrange for Council to carry out pre-commencement and\npost demolition inspections of the site.\nBUILDING WORK","stage":"ongoing","stage_basis":"heading","page":10},{"label":"12","code":null,"number":"12","title":"Silt-arrestor pit","text":"A silt-arrestor pit is to be designed and constructed inside the front boundary\nprior to the discharge outlet to street gutter.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"13","code":null,"number":"13","title":"Long Service Levy","text":"Before the issue of the relevant construction certificate the long service levy of $\n8,222.00, as calculated at the date of this consent, must be paid to the Long Service\nCorporation of Council under the Building and Construction industry Long Service\nPayments Act 1986, section 34, and evidence of the payment is to be provided to\nthe certifier.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"14","code":null,"number":"14","title":"Payment of security deposits","text":"Before the issue of the relevant construction certificate, the applicant must:\na) make payment of $24,514.00 for a security deposit and $155.00 for\nAdministration Fee to the consent authority, and\nb) if a principal certifier is required to be appointed for the development -\nprovide the principal certifier with written evidence of the payment and the\namount paid.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"15","code":null,"number":"15","title":"Basix Commitments","text":"The approved BASIX Certificate must be submitted to the Principal Certifier with\nthe application for a Construction Certificate.\nAll measures and commitments as detailed in the BASIX Certificate No.\n1816349M_04 must be implemented on the plans lodged with the application for\nthe Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"16","code":null,"number":"16","title":"Low Reflectivity Roof","text":"Roofing materials must be low glare and reflectivity. Details of finished external\nmaterials must be provided to the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"17","code":null,"number":"17","title":"Stormwater System","text":"The submitted stormwater plan has been assessed as a concept plan only. Final\ndetailed plans of the drainage system in accordance with Council’s Stormwater\nManagement Code and AS/NZS 3500.3: 2015 (as amended), prepared by a\nsuitably qualified professional engineer specialising in hydraulic engineering, must\nbe submitted for approval to the Principal Certifier with the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"18","code":null,"number":"18","title":"Erosion and sediment control plan","text":"Before the issue of a construction certificate, an erosion and sediment control\nplan must be prepared by a suitably qualified person in accordance with the\nfollowing documents and provided to the certifier or council (where a certifier is\nnot required):\na) Council’s relevant development control plan,\nb) the guidelines set out in the NSW Department of Housing manual ‘Managing\nUrban Stormwater: Soils and Construction Certificate’ (the Blue Book) (as\namended from time to time), and\nc) the ‘Guidelines for Erosion and Sediment Control on Building Sites’\n(Department of Planning, Housing and Infrastructure)\n(dated 2024, as amended from time to time)","stage":"before_cc","stage_basis":"heading","page":12},{"label":"19","code":null,"number":"19","title":"Dial Before Your Dig","text":"The applicant must contact Home | Before You Dig Australia (BYDA) to obtain a\nService Diagram prior to the issuing of the Construction Certificate. The sequence\nnumber obtained from “Dial Before You Dig” must be forwarded to Council’s\nEngineers for their records.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"20","code":null,"number":"20","title":"Structural Details","text":"Engineer’s details for all reinforced concrete work, structural beams, columns &\nother structural members must be prepared by a suitably qualified practising\nStructural Engineer. These details are to be submitted to the Principal Certifier\nfor approval.\nA copy must be forwarded to Council where Council is not the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"21","code":null,"number":"21","title":"Off Street Parking - Compliance with AS2890","text":"All driveways, access ramps, vehicular crossings and car parking spaces must be\ndesigned and constructed in accordance with the current version of Australian\nStandards, AS 2890.1 (for car parking facilities), AS 2890.6 (parking for people with\ndisabilities) and AS 2890.2 (for commercial vehicle facilities).","stage":"before_cc","stage_basis":"heading","page":13},{"label":"22","code":null,"number":"22","title":"Construction Site Management Plan","text":"Before the issue of a construction certificate, a construction site management\nplan must be prepared, and provided to the certifier or council (where a certifier\nis not required). The plan must include the following matters:\na) The location and materials for protective fencing and hoardings on the\nperimeter of the site;\nb) Provisions for public safety;\nc) Pedestrian and vehicular site access points and construction activity zones;\nd) Details of construction traffic management including:\ni) Proposed truck movements to and from the site;\nii) Estimated frequency of truck movements; and\niii) Measures to ensure pedestrian safety near the site;\ne) Details of bulk earthworks to be carried out;\nf) The location of site storage areas and sheds;\ng) The equipment used to carry out works;\nh) The location of a garbage container with a tight-fitting lid;\ni) Dust, noise and vibration control measures;\nj) The location of temporary toilets;\nk) The protective measures for the preservation of trees on-site and in\nadjoining public areas including measures in accordance with:\ni) AS 4970 - Protection of trees on development sites;\nii) An applicable Development Control Plan;\niii) An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times\nwhile work is being carried out","stage":"before_cc","stage_basis":"heading","page":13},{"label":"23","code":null,"number":"23","title":"Waste Management Plan - an approved document of this consent","text":"Before the issue of a construction certificate, a waste management plan for the\ndevelopment must be provided to the certifier or council (where a certifier is not\nrequired).","stage":"before_cc","stage_basis":"heading","page":13},{"label":"24","code":null,"number":"24","title":"Tree Bond","text":"A tree bond (calculated in accordance with Council’s adopted Fees and Charges)\nmust be paid to Council, prior to the issue of a Construction Certificate.\nTree\nnumber\nSpecies Name Height Bond Fee\nT1 Lophostemon confertus 13.0 metres $23,698.00\nA tree bond administration fee of $155.00 applies.\nThe deposit is required as security against any damage to existing trees to be\nretained on Council’s Road reserve, during works on the site. The applicant must\nbear the cost of all restoration works to Council’s property damaged during the\ncourse of this development.\nA Tree Protection fence consisting of a fully supported chainmesh fence 1.8\nmetres height x 2 metres clear of the base of the tree at any one point must be\nerected around the nominated street trees in front of 75 Chalmers Road\nStrathfield and any trees in adjacent reserves and parks if applicable, unless\notherwise specified in AS4970-2025.\nThe Tree Protection fence is to extend up to the back of the kerb and to the edge\nof the footpath,\nTree Protection fence is to be in place prior to commencement of demolition/\nconstruction works.\nPayment may be accepted in the form of a bank cheque, credit card or bank\nguarantee. An administration fee applies to all bonds in accordance with Council’s\nadopted Fees and Charges.\nA request for refund of the Tree Bond must be made in writing.\nTree Bonds may be forfeited if a tree is dead, made dangerous or has been\nterminally damaged, or will be held until tree/s have fully recovered from the\nconstruction damage or were replacement/planted trees have become fully\nestablished and are over 6 metres in height.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"25","code":null,"number":"25","title":"Landscape Plans","text":"All landscape works must be carried out in accordance with the approved\nlandscape plans.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"26","code":null,"number":"26","title":"Tree Removal/Pruning Prohibited","text":"The removal or pruning (branches or roots) of any trees on the subject property\n(excluding those approved for removal in these conditions or species on Council’s\nexempt species list), Council’s public footway, public reserves or on neighbouring\nproperties must not be undertaken other than in accordance with the express\nprovisions of this consent.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"27","code":null,"number":"27","title":"Tree Protection and Retention","text":"The following trees are to be protected throughout the course of all demolition and\nconstruction works. Tree protection is to be in place prior to commencement of\ndemolition works.\nTree No. Tree Species Location of Tree TPZ\nT1 Lophostemon\nconfertus\nCouncil Verge 8.5 metres\nT5 Cinnamomum\ncamphora\nRear Neighbour’s Tree 11.4 metres\nT6 Cinnamomum\ncamphora\nRear Neighbour’s Tree 10.4 metres\nAll works within Tree TPZ is to be by hand tools only as per the Aboricultural\nMethod Statement of the AIA Report.\nA Project Arborist must be present on -site during the stages of construction\nwhen works are being undertaken that could impact on the tree canopy or root\nzone within the Tree Protection Zone to implement the tree protection measures\nas required.\nNo services shall be installed within the Tree Protection Zone of the tree unless\napproved by Council. Tree protection fencing shall be kept in place during\ndemolition, construction and also have a sign displaying ‘Tree Protection Zone’\nattached to the fence and must also include the name and contact details of the\nProject Arborist.\nWhere the Tree Protection Zone of trees on site or adjoining sites become\ncompromised by any excavation works, the Project Arborist shall be consulted to\nestablish the position of any major roots and determine the necessary measures\nto protect these roots. The recommendations of the Project Arborist shall be\nsubmitted to Council prior to any further demolition or construction works taking\nplace","stage":"before_cc","stage_basis":"heading","page":14},{"label":"28","code":null,"number":"28","title":"Tree Removal & Replacement","text":"Tree removal\nPermission is granted for the removal of the following trees:\nTree No. Tree species Location\nT2 Callistemon viminalis Front Setback\nT3 Syagrus romanzoffiana Front Setback\nT4 Cinnamomum camphora Front Setback\nNo Permission is granted for the removal of any other trees on site.\nGeneral Tree Removal Requirements\nAll tree removal work must be undertaken by a minimum Certificate 3 (AQF 3)\nqualified Arborist who is currently a member or eligible for membership to\nArboriculture Australia (AA) or the Tree Contractors Association Australia\n(TCAA), to ensure that removal is undertaken in a safe manner and complies\nwith the AS 4373-2007 - Pruning of Amenity Trees and Amenity Tree Industry\nCode of Practice (Safework NSW, August 1998).\nTree Replacement\nAll trees permitted to be removed by this consent must be replaced 2 trees for\neach tree removed by species selected from Council’s Suggested Tree Species List\nand must be able to achieve a minimum mature height of 10 metres.\nReplacement trees must be a minimum 75 litre container size. Trees are to meet\nthe requirements of AS 2303: 2018- Tree Stock for Landscape Use. Trees must be\ntrue to type, healthy and vigorous at time of delivery and planting, must be pest\nand disease free, free from injury and wounds and self-supporting; and must be\nmaintained until maturity.\nAll trees must be staked and tied with a minimum of three (3) hardwood stakes.\nTies must be hessian and fixed firmly to the stakes, one tie at half the height of\nthe main stem, others as necessary to stabilise the plant.\nTrees within lawn areas or street verges must have Tree Guard bark protectors\ninstalled around the base of trunks to protect from damage by trimmers and\nmowers.\nRoot deflection barriers having a minimum depth of 600mm are to be installed\nadjacent to all footpaths and driveways.\nSoil conditioner, fertilizer, and moisture retention additives must be applied in\naccordance with manufacturer’s recommendations, and mixed into the\nbackfilling soil after planting tree/s.\nA minimum 75mm depth of organic mulch must be placed around the tree,\nextending to a minimum radius 0.5m from the base of the trunk. Mulch shall be\n‘dished’ around the base of the tree’s trunk.\nDetails demonstrating compliance must be demonstrated to the Principal\nCertifier, prior to the issue of any Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"29","code":null,"number":"29","title":"Pump-Out System Design for Stormwater Disposal","text":"The design of the pump-out system for stormwater disposal will be permitted for\ndrainage of basement areas only, and must be designed in accordance with the\nfollowing criteria:\n(a) The pump system must consist of two pumps, connected in parallel, with\neach pump being capable of emptying the holding tank at the rate equal\nto the rate of inflow for the one -hour duration storm. The holding tank\nmust be capable of holding four hour’s run off from a one-hour duration\nstorm of the 1 in 100 year storm;\n(b) The pump system must be regularly maintained and serviced, every six\n(6) months; and\n(c) Any drainage disposal to the street gutter from a pump system must have\na stilling sump provided at the property line, connected to the street\ngutter by a suitable gravity line.\nDetails and certification of compliance from a suitably qualified professional\nengineer specialising in hydraulic engineering must be provided to the Principal\nCertifier for approval with the Construction Certificate application.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"30","code":null,"number":"30","title":"Geotechnical Report","text":"The applicant must submit a Geotechnical Report, prepared by a suitably qualified\nprofessional engineer specialising in geotechnical engineering. The Geotechnical\nReport must address dilapidation reports, all site works and construction. This is\nto be su bmitted to the Principal Certifier and Council (where Council is not the\nCertifier) before the issue of the Construction Certificate and must include:\n(a) Investigations certifying the stability of the site and specifying the design\nconstraints to be placed on the foundation, any earthworks, stabilization\nworks and any excavations.\n(b) Dilapidation Reports on the adjoining properties including, but not limited to\n73 Chalmers Rd and 77 Chalmers Rd prior to any excavation of site works. The\nDilapidation Report must include assessments on, but not limited to, the\ndwellings at those addresses and any external paths, grounds etc. This must\nbe submitted to the Principal Certifier and the adjoining resi dents as part of\nthe application for the Construction Certificate. Adjoining residents must be\nprovided with the report five (5) working days prior to any works on the site.\n(c) On-site guidance by a vibration specialist during the early part of excavation.\n(d) Measures to minimise vibration damage and loss of support to other\nbuildings. Where possible any excavation into rock is to be carried out with\ntools such as rock saws which reduce vibration to adjoining buildings and\nassociated structures. Where a hydraul ic hammer is to be used within 30\nmetres of any building (other than a path or a fence) the report must detail\nthe maximum size of hammer to be used and provide all reasonable\nrecommendations to manage impacts.\n(e) Sides of the excavation must be piered prior to any excavation occurring to\nreinforce the walls of the excavation to prevent any subsidence to the\nrequired setbacks and neighbouring sites.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"31","code":null,"number":"31","title":"Compliance with Swimming Pool Act 1992","text":"The alterations and additions to the dwelling house subject of this consent must\nnot generate any non-compliance with the Swimming Pools Act 1992, Swimming\nPool Regulation 2018, and the Building Code of Australia. Details of compliance\nmust be the illustra ted on the plans lodged with the application for the\nConstruction Certificate","stage":"before_cc","stage_basis":"heading","page":17},{"label":"32","code":null,"number":"32","title":"Swimming Pools - Use and Maintenance","text":"The following apply to the construction, use and maintenance of swimming pools\nand spas:\n(a) No ground level may be raised or filled except where shown specifically on\nthe approved plans;\n(b) All pool or spa waste water is to be discharged to the sewer according to the\nrequirements of Sydney Water;\n(c) The swimming pool must not be used for commercial or professional\npurposes;\n(d) Paved areas must be designed to ensure drainage flows to the landscaped\nareas or a suitable lawful drainage system; and\n(e) Any lighting external to the pool or spa must be arranged to minimise glaring\nnuisance to adjoining owners.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"33","code":null,"number":"33","title":"Street and Reserve Tree Protection and Retention","text":"A protective fence consisting of a fully supported chainmesh fence 1.8 metres\nheight x 2 metres clear of the base of the tree at any one point must be erected\naround the nominated street trees in front of 75 Chalmers Road, Strathfield, and\nany trees in adjacent reserves and parks if applicable, unless otherwise specified\nin AS4970-2009. The fence is to extend up to the back of the kerb and to the\nedge of the footpath. No services shall be installed within the Tree Protection\nZone of the tree unless approved by Council. Tree protection fencing shall be\nkept in place during demolition, construction and also have a sign displaying ‘Tree\nProtection Zone’ attached to the fence and must also include the name and\ncontact details of the Project Arborist.\nNo soil, fill, building materials or waste should be placed or disposed of within the\nprotection area.\nTree No. Tree Species Location of Tree\nT1 Lophostemon confertus Council Verge\nShould replacement or repair of the public footpath or vehicle crossing within the\nTree Protection Zone area of a street tree be required, Council’s Urban Forest\nSupervisor is to be notified (with minimum 24hrs notice) of the intent to\nundertake the works and is to attend a site inspection after the existing footpath\nhas been lifted but prior to any preparation works for laying of the new path. No\nstreet tree roots are to be cut without the Approval of Council. Failure to comply\nwith this condition may result in the forfeiting of the Tree Bond should the street\ntree’s health or structure be compromised.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"34","code":null,"number":"34","title":"Compliance with Flood Study","text":"The development must be designed to conform to the recommendations and\nconclusions of the submitted flood study prepared by RCO Engineering Pty Ltd\ndated 11/12/2025\nThis must include, but not be limited to, any recommendations for the following:","stage":"before_cc","stage_basis":"heading","page":18},{"label":"35","code":null,"number":"35","title":"Stormwater Drainage Plan Details","text":"Stormwater drainage plans including pipe sizes, type, grade, length, invert levels,\ndimensions and types of drainage pits prepared by a suitably qualified\nprofessional engineering specialising in hydraulic engineering must be submitted\nwith the Construction Certificate application.\nThese plans must be prepared in accordance with the Australian Institute of\nEngineers Australian Rainfall and Runoff (1987) and Council’s Stormwater\nManagement Code.","stage":"before_work","stage_basis":"heading","page":19},{"label":"36","code":null,"number":"36","title":"Demolition & Asbestos","text":"The demolition work must comply with the provisions of Australian Standard\nAS2601:2001 - Demolition of Structures, NSW Work Health & Safety Act 2011 and\nthe NSW Work Health & Safety Regulation 2011 . The work plans required by\nAS2601:2001 must be accompanied by a written statement by a suitably qualified\nperson that the proposals contained in the work plan comply with the safety\nrequirements of the Standard. The work plans and the safety statement must be\nsubmitted to the Principal Certifier prior to the commencement of works.\nFor demolition work which involves the removal of asbestos, the asbestos\nremoval work must be carried out by a licensed asbestos removalist who is\nlicensed to carry out the work in accordance with the NSW Work Health & Safety\nAct 2011 and the NSW Work Health & Safety Regulation 2011 unless specified in\nthe Act or Regulation that a license is not required.\nAll demolition work including the removal of asbestos, must be undertaken in\naccordance with the Demolition Code of Practice (NSW Work Cover July 2015)","stage":"before_work","stage_basis":"heading","page":19},{"label":"37","code":null,"number":"37","title":"Demolition Notification Requirements","text":"The following notification requirements apply to this consent:\n(a) The builder must notify adjoining residents five (5) working days prior to\ndemolition. Such notification will be a clearly written note giving the date\ndemolition will commence, contact details of the builder, licensed asbestos\ndemolisher and the appropriate regulatory authority. Notification must be\nplaced in the letterbox of every premises (including every residential flat or\nunit, if any) either side and immediately at the rear of the demolition site.\n(b) Five (5) working days prior to demolition, the builder must provide written\nnotification to Council advising of the demolition date, details of the SafeWork\nlicensed asbestos demolisher and the list of residents advised of the\ndemolition.\n(c) On demolition sites where buildings to be demolished contain asbestos, a\nstandard commercially manufactured sign containing the words “DANGER\nASBESTOS REMOVAL IN PROGRESS” measuring not less than 400mm x\n300mm must be erected in a prominent visible position (from street frontage)\non the site. The sign must be erected prior to demolition work commencing\nand will remain in place until such time as all asbestos material has been\nremoved from the site to an approved waste facility.","stage":"before_work","stage_basis":"heading","page":19},{"label":"38","code":null,"number":"38","title":"Demolition Work Involving Asbestos Removal","text":"Work involving bonded asbestos removal work (of an area of more than 10 square\nmetres) or friable asbestos removal work must be undertaken by a person who\ncarries on a business of such removal work in accordance with a licence under\nclause 458 of the Work Health and Safety Regulation 2011","stage":"before_work","stage_basis":"heading","page":20},{"label":"39","code":null,"number":"39","title":"Utility Arrangements","text":"Arrangements must be made with utility authorities in respect to the services\napplied those authorities to the development. The cost associated with the\nprovision or adjustment of services within the road and footway areas will be at\nthe applicant’s expense.","stage":"before_work","stage_basis":"heading","page":20},{"label":"40","code":null,"number":"40","title":"Erosion and sediment controls in place","text":"Before any site work commences, the principal certifier or council (where a\nprincipal certifier is not required), must be satisfied the erosion and sediment\ncontrols in the erosion and sediment control plan which was provided to the\nprincipal certifier or council (where a principal certifier is not required) are in\nplace. These controls must remain in place until any bare earth has been\nrestabilised in accordance with the\nerosion and sediment control plan.","stage":"before_work","stage_basis":"heading","page":20},{"label":"41","code":null,"number":"41","title":"Tree protection measures","text":"","stage":"before_work","stage_basis":"heading","page":20},{"label":"42","code":null,"number":"42","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a\nsuitably qualified engineer detailing the structural condition of adjoining\nbuildings, structures or works and public land, to the satisfaction of the principal\ncertifier or council (where a principal certifier is not required).\nwhere access has not been granted to any adjoining properties to prepare the\ndilapidation report, the report must be based on a survey of what can be\nobserved externally and demonstrate, in writing, to the satisfaction of the\nprincipal certifier or council (where a principal certifier is not required), that all\nreasonable steps were taken to obtain access to the adjoining properties.\nNo less than 7 days before any site work commences, adjoining building owner(s)\nmust be provided with a copy of the dilapidation report for their property(ies) and\na copy of the report(s) must be provided to council (where council is not the\nprincipal certifier) at the same time.","stage":"during_work","stage_basis":"heading","page":21},{"label":"43","code":null,"number":"43","title":"Dust Control","text":"Where a dust nuisance is likely to occur, suitable screens and barricades must be\nerected during the demolition, excavation and building works. Water sprays must\nbe used on the site to reduce the emission of dust. Screening must consist of a\nminimum 2 metr es height of shade cloth or similar material secured to a chain\nwire fence or the like and must be modified as required should it fail to adequately\ncontrol any dust nuisance.","stage":"during_work","stage_basis":"heading","page":21},{"label":"44","code":null,"number":"44","title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor building construction and delivery of machinery and materials from 7:00am\nto 5:00pm on Monday to Saturday (excluding Public Holidays)\nFor demolition, excavation and/or construction works that involve heavy\nmachinery, noisy trades, or the like from 7:00am to 5:00pm on Monday to Friday\n(excluding Public Holidays)\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":21},{"label":"45","code":null,"number":"45","title":"Ground Levels and Retaining Walls","text":"The ground levels of the site must not be excavated, raised or filled and retaining\nwalls constructed on the allotment boundary, except where indicated on\napproved plans or approved by Council.","stage":"during_work","stage_basis":"heading","page":22},{"label":"46","code":null,"number":"46","title":"Cost of Work to be Borne by the Applicant","text":"The applicant must pay the cost of all works associated with the construction of\nthe development that occurs on Council property. Care must be taken to protect\nCouncil’s roads, including the made footway, kerbs, etc, and where plant and\nvehicles enter the site, the footway must be protected against damage by deep -\nsectioned timber members laid crosswise, held together by hoop iron straps and\nchamfered at their ends. This construction must be maintained in a state of good\nrepair and condition throughout the course of construction.","stage":"during_work","stage_basis":"heading","page":22},{"label":"47","code":null,"number":"47","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved\nremoval, relocation or reconstruction of infrastructure (including ramps,\nfootpaths, kerb and gutter, light poles, kerb inlet pits, service provider pits, street\ntrees or any other infrastructure in the street footpath area) must be paid as\ndirected by the consent authority.","stage":"during_work","stage_basis":"heading","page":22},{"label":"48","code":null,"number":"48","title":"Obstruction of Road or Footpath","text":"The use of the road or footpath for the storage of any building materials, waste\nmaterials, temporary toilets, waste or skip bins, or any other matter is not\npermitted unless separately approved by Council under Section 138 of the Roads\nAct 1993 and under Section 68 of the Local Government Act 1993 . Penalty\ninfringement Notices may be issued for any offences and severe penalties apply.","stage":"during_work","stage_basis":"heading","page":22},{"label":"49","code":null,"number":"49","title":"Construction Management Plan","text":"The builder must ensure that the approved Construction Traffic Management Plan\nis to be strictly complied with and kept on site at all times during construction\nworks.","stage":"during_work","stage_basis":"heading","page":22},{"label":"50","code":null,"number":"50","title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each\ncritical stage inspection unless the principal certifier is satisfied the work may\nproceed in accordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":22},{"label":"51","code":null,"number":"51","title":"Registered Surveyors Report","text":"A report must be submitted to the Principal Certifier at each of the following\napplicable stages of construction:\n(a) Set out before commencing excavation.\n(b) Floor slabs or foundation wall, before formwork or commencing\nbrickwork.\n(c) Completion of Foundation Walls - Before any construction of flooring,\ndetailing the location of the structure relative to adjacent boundaries\nand floor levels relative to the datum shown on the approved plans.\n(d) Completion of Floor Slab Formwork - Before pouring of concrete/walls\nconstruction, detailing the location of the structure relative to adjacent\nboundaries and floor levels relative to the datum shown on the approved\nplans. In multi -storey buildings a furt her survey must be provided at\neach subsequent storey.\n(e) Completion of any Pool Formwork - Before concreting of pool shell,\ndetailing the location of the pool relative to the adjacent boundaries and\nits height relative to the datum shown on the approved plans.\n(f) Completion of any Roof Framing - Before roof covered detailing\neaves/gutter setback from boundaries.\n(g) Completion of all Work - Detailing the location of the structure (including\neaves/gutters) relative to adjacent boundaries and its height relative to\nthe datum shown on the approved plans. A final Check Survey must\nindicate the reduced level of the main ridge.\nWork must not proceed beyond each stage until the Principal Certifier is satisfied\nthat the height and location of the building is proceeding in accordance with the\napproved plans.","stage":"during_work","stage_basis":"heading","page":23},{"label":"52","code":null,"number":"52","title":"Implementation of the site management plans while site work is being carried","text":"out:\na) the measures required by the construction site management plan and the\nerosion and sediment control plan (plans) must be implemented at all\ntimes, and\nb) a copy of these plans must be kept on site at all times and made available\nto council officers upon request.","stage":"during_work","stage_basis":"heading","page":23},{"label":"53","code":null,"number":"53","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must\nbe maintained in good condition in accordance with:\na) the construction site management plan required under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development\nsites,\nc) Council’s relevant development control plan (in force as at the date of\ndetermination of this consent) and\nd) any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery,\nbuilders refuse, spoil and materials remain outside tree protection zones.","stage":"during_work","stage_basis":"heading","page":24},{"label":"54","code":null,"number":"54","title":"Waste management","text":"While site work is being carried out:\na) all waste management must be undertaken in accordance with the waste\nmanagement plan, and\nb) upon disposal of waste, records of the disposal must be compiled and\nprovided to the Certifier, or Council where a certifier is not required,\ndetailing the following:\ni) The contact details of the person(s) who removed the waste\nii) The waste carrier vehicle registration\niii) The date and time of waste collection\niv) A description of the waste (type of waste and estimated quantity)\nand whether the waste is to be reused, recycled or go to landfill\nv) The address of the disposal location(s) where the waste was taken\nvi) The corresponding tip docket/receipt from the site(s) to which the\nwaste is transferred, noting date and time of delivery, description\n(type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order\nor Exemption, records in relation to that Order or Exemption must be\nmaintained and provided to the principal certifier and council.","stage":"during_work","stage_basis":"heading","page":24},{"label":"55","code":null,"number":"55","title":"Connection to the Network","text":"Where works within the road reserve are to be carried out by the developer, a\nRoad Opening Permit must be obtained from Council before the\ncommencement of any work.","stage":"during_work","stage_basis":"heading","page":24},{"label":"56","code":null,"number":"56","title":"Soil management","text":"While site work is being carried out, the principal certifier or council (where a\nprincipal certifier is not required) must be satisfied all soil removed from or\nimported to the site is managed in accordance with the following requirements:\na) all excavated material removed from the site must be classified in\naccordance with the epa’s waste classification guidelines before it is\ndisposed of at an approved waste management facility and the\nclassification and the volume of material removed must be reported to the\nprincipal certifier or council (where a principal certifier is not required).\nb) All fill material imported to the site must be:\ni) Virgin Excavated Natural Material as defined in Schedule 1 of the\nProtection of the Environment Operations Act 1997, or\nii) a material identified as being subject to a resource recovery exemption\nby the NSW EPA, or\niii) a combination of Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997\nand a material identified as being subject to a resource recovery\nexemption by the NSW EPA.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"57","code":null,"number":"57","title":"Swimming Pools - Filling with Water","text":"The pool must not be filled until the safety fences have been completed in\naccordance with the approved plans and specifications and inspected by the\nPrincipal Certifier","stage":"before_oc","stage_basis":"heading","page":25},{"label":"58","code":null,"number":"58","title":"BASIX Certificate","text":"All energy efficiency measures as detailed in the approved BASIX Certificate in the\nplans approved with the Development Consent, must be implemented before the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"59","code":null,"number":"59","title":"BASIX Compliance Certificate","text":"A Compliance Certificate must be provided to the Principal Certifier regarding the\nimplementation of all energy efficiency measures as detailed in the approved\nBASIX Certificate before any Occupation Certificate is issued.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"60","code":null,"number":"60","title":"Completion of Landscape Works and Tree Works","text":"The approved landscape works have identified that the side setback area between\nthe dwelling and boundary be nominated as landscaped area to ensure\ncompliance with the minimum landscape area requirements. In this regard, this\narea must be maintained as la ndscaped area and must only be used for growing\nplants, grasses and trees and must not include any building, structure or hard\npaving (including rainwater tanks, air -conditioning units of ground mounted hot\nwater systems).","stage":"before_oc","stage_basis":"heading","page":25},{"label":"61","code":null,"number":"61","title":"Minor Development","text":"Internal driveways and parking spaces must be adequately paved with concrete\nor bitumen, or interlocking pavers to provide a dust-free surface.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"62","code":null,"number":"62","title":"Stormwater Certification of the Constructed Drainage Works (Minor)","text":"The constructed stormwater system must be certified by a suitably qualified\nperson, in accordance with Council’s Stormwater Management Code, prior to the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"63","code":null,"number":"63","title":"Vehicular Crossing - Minor Development","text":"The vehicular crossing and footpath works must be constructed by a private\ncontractor at the expense of the applicant, in accordance with the Works Permit\nApproval issued by Council’s Engineering Design Services and in accordance with\nCouncil’s Driveway Specifications.\nAny existing vehicular crossing and laybacks which are redundant must be\nremoved. The kerb and gutter, any other footpath and turf areas must be restored\nat the expense of the applicant and in accordance with Council’s Driveway\nSpecifications.\nThe work must be completed before the issue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"64","code":null,"number":"64","title":"Release of securities","text":"When Council receives an occupation certificate, an application may be lodged to\nrelease the securities held in accordance with Council’s Policy.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"65","code":null,"number":"65","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":26},{"label":"66","code":null,"number":"66","title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":27},{"label":"67","code":null,"number":"67","title":"Electricity Supply","text":"Prior to the issue of any Occupation Certificate, evidence must be provided\ndemonstrating that the development has been connected to the Ausgrid network.","stage":"before_oc","stage_basis":"heading","page":27},{"label":"68","code":null,"number":"68","title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be\nobtained from the relevant authority that any adjustment or augmentation of any\npublic utility services including gas, water, sewer, electricity, street lighting and\ntelecommunications, required as a result of the development, have been\ncompleted and this confirmation must be provided to the principal certifier.","stage":"before_oc","stage_basis":"heading","page":27},{"label":"69","code":null,"number":"69","title":"Restriction to User and Positive Covenant for Stormwater Management System","text":"Prior to the issue of any Occupation Certificate, the applicant must register a\nPositive Covenant and a Restriction as to User under section 88E and or section\n88B of the Conveyancing Act as appropriate in favour of Council, ensuring the\nongoing retention, maintenance and operation of the stormwater facility (on-site\ndetention, pump-out, charged lines, water sensitive urban design, surface flow\npath, finished pavement and ground levels etc.).\nWhere any drainage line or service conduit is to traverse any property other than\nthat which it serves, an appropriate easement will be required. In this case, the\napplicant must register an easement no less than 1200mm wide over the\nproposed drainage line or service concurrently with any subdivision registration.\nThe wording on the 88E and or 88B Instrument is to make reference to the Council\nfile where the Construction plans and the Work As Executed (as built), plans are\nheld. Typical wording can be obtained from Council's Specification for the\nManagement of Stormwater document.","stage":"before_oc","stage_basis":"heading","page":27},{"label":"70","code":null,"number":"70","title":"Maintenance Schedule - On-site Stormwater Management","text":"A Maintenance Schedule for the proposed on -site stormwater management\nmeasures must be prepared by a suitably qualified professional hydraulic\nengineer and submitted to Council. The Maintenance Schedule must outline the\nrequired maintenance works, how and when these will be done and who will be\ncarrying out these maintenance works.","stage":"before_oc","stage_basis":"heading","page":28},{"label":"71","code":null,"number":"71","title":"Post-construction dilapidation report","text":"Before the issue of an occupation certificate a post- construction dilapidation\nreport must be prepared by a suitably qualified engineer, to the satisfaction of\nthe principal certifier or council (where a principal certifier is not required),\ndetailing whether:\na) after comparing the pre-construction dilapidation report to the post-\nconstruction dilapidation report required under this condition, there has\nbeen any structural damage to any adjoining buildings; and\nb) where there has been structural damage to any adjoining buildings, that it\nis a result of the work approved under this development consent, and\na copy of the post-construction dilapidation report must be provided to council\n(where council is not the principal certifier or a principal certifier is not required)\nand to the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":28},{"label":"72","code":null,"number":"72","title":"Works-as-executed plans and any other documentary evidence","text":"Before the issue of the relevant occupation certificate, works-as-executed plans,\nany compliance certificates and any other evidence confirming the following\ncompleted works must be submitted to the satisfaction of the principal certifier:\na) All stormwater drainage systems and storage systems, and\nb) The following matters that council requires to be documented Positive\nCovenant and Restriction-on-Use documents\nc) A copy of the plans must be provided to council with the Occupation\nCertificate.","stage":"before_oc","stage_basis":"heading","page":28},{"label":"73","code":null,"number":"73","title":"Maintenance of Landscaping","text":"All trees and plants forming part of the landscaping must be maintained.\nMaintenance includes watering, weeding, removal of rubbish from tree bases,\nfertilising, pest and disease control, replacement of dead or dying plants and any\nother operations required to maintain healthy trees, plants and turfed areas.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"74","code":null,"number":"74","title":"Greywater System","text":"In order to conserve and re -use water, Council encourages all development for\nnew dwellings to incorporate a greywater reuse system. The system can\nincorporate a greywater diversion device or a domestic greywater treatment\nsystem. Any system installed must ensure that it complies with the Plumbing Code\nof Australia. Th system must be maintained at all times and must not result in any\nadverse amenity impacts on the subject premises and surrounding properties.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"75","code":null,"number":"75","title":"Maintenance of wastewater and stormwater treatment device","text":"During occupation and ongoing use of the building, all wastewater and\nstormwater treatment devices (including drainage systems, sumps and traps, and\non-site detention) must be regularly maintained to remain effective and in\naccordance with any positive covenant (if applicable).","stage":"ongoing","stage_basis":"heading","page":29},{"label":"76","code":null,"number":"76","title":"Entering and Exiting of Vehicles","text":"All vehicles must enter and exit the premises in a forward direction.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"77","code":null,"number":"77","title":"Swimming Pools - Resuscitation Notice","text":"An expired air resuscitation warning notice complying with the Swimming Pools\nAct 1992 must be affixed in a prominent position adjacent to the pool.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"78","code":null,"number":"78","title":"Private Swimming Pools & Spas - Pump Noise","text":"The swimming pool or spa pump and associated equipment must be located so\nthat the noise emitted does not exceed 5db(A) above the background level. If this\ncannot be achieved a ventilated and sound -proofed enclosure the pump to\nachieve the required noise levels.\nSwimming pool is to be installed with a timer that limits the recirculation and\nfiltration systems operation such that it does not emit noise that can be heard\nwithin a habitable room in any other residential premises (regardless of whether\nany door or window to that room is open):\n(a) before 8 am or after 8 pm on any Sunday or public holiday, or\n(b) before 7 am or after 8pm on any other day.","stage":"ongoing","stage_basis":"heading","page":29}]});
